def approval_rate(rows, channel, convention="all"):
    sub = [r for r in rows if r["channel"] == channel
           and (convention == "all" or r["status"] != "cancelled")]
    try:
        return round(100 * sum(r["status"].startswith("approved") for r in sub) / len(sub), 1)
    except ZeroDivisionError:
        return None
for ch in ["app", "branch", "partner"]:
    print(ch, approval_rate(rows, ch), approval_rate(rows, ch, "decided"))
print(approval_rate(rows, "crypto"))   # None

